// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guessHash, address player) public {
        vm.assume(player != address(0) && player.code.length == 0 && player != address(this));

        vm.deal(player, 1 ether);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guessHash);

        bool ok;
        vm.prank(player);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "settle should not succeed before block.number > lock block");
    }
}
